import json
from datetime import date
from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message

class SynCarePlanFacts(Component):
    display_name = "SynCare Plan Fact Gate"
    description = "Deterministic pre-generation fact validation, intensity injection and fail-closed routing."
    inputs = [MessageTextInput(name="input_value", display_name="Scored Episode and Scheduling Facts", required=True)]
    outputs = [Output(name="facts", display_name="Validated Facts", method="validated_facts", group_outputs=True), Output(name="error", display_name="Fact Error JSON", method="fact_error", group_outputs=True)]

    def _prepare(self):
        if hasattr(self, "_prepared"):
            return self._prepared
        missing = []
        try:
            raw = self.input_value
            source = json.loads(raw.text if isinstance(raw, Message) else str(raw))
            scored = source["f1_scored_output"]
            episode = scored["episode"]
            keys = {"diagnosis", "medications", "instructions", "followup_needs", "length_of_stay_days", "admission_type", "comorbidity_count", "admissions_prior_12m"}
            if not isinstance(episode, dict) or set(episode) != keys:
                raise ValueError("Episode must preserve all eight F1 fields")
            if not isinstance(episode["diagnosis"], str) or not episode["diagnosis"].strip():
                missing.append("diagnosis")
            for field in ("medications", "instructions", "followup_needs"):
                if not isinstance(episode[field], list) or not all(isinstance(v, str) and v.strip() for v in episode[field]):
                    raise ValueError("Episode arrays must contain factual strings")
            if not episode["medications"]:
                missing.append("medications")
            for field in ("length_of_stay_days", "comorbidity_count", "admissions_prior_12m"):
                if episode[field] is not None and (type(episode[field]) is not int or episode[field] < 0):
                    raise ValueError("Episode count fields must be nonnegative integers or null")
            if episode["admission_type"] not in ("emergency", "elective", "unknown"):
                raise ValueError("Invalid admission_type")
            score = scored["score"]
            tier = scored["tier"]
            if type(score) is not int or score < 0 or tier != ("HIGH" if score >= 4 else "MEDIUM" if score >= 2 else "LOW"):
                raise ValueError("F1 score/tier mismatch")
            if scored["label"] != "demo-heuristic-v1":
                raise ValueError("Invalid F1 demo label")
            if not isinstance(source.get("patient_id"), str) or not source["patient_id"].strip():
                missing.append("patient_id")
            for field in ("followup_date", "hotline"):
                if not isinstance(source.get(field), str) or not source[field].strip():
                    missing.append(field)
            if missing:
                raise ValueError("Required facts absent; generation skipped")
            if date.fromisoformat(source["followup_date"]).isoformat() != source["followup_date"]:
                raise ValueError("followup_date must be an explicitly supplied ISO date")
            activities = {"HIGH": ["Telepon perawat dalam 24 jam.", "Check-in setiap hari."], "MEDIUM": ["Check-in setiap 2 hari.", "Kunjungan rawat jalan dalam 7 hari."], "LOW": ["Check-in setiap minggu.", "Kunjungan rawat jalan dalam 30 hari."]}[tier]
            codes = {"HIGH": ["nurse-call-within-24h", "daily-checkin"], "MEDIUM": ["checkin-every-2-days", "outpatient-within-7-days"], "LOW": ["weekly-checkin", "outpatient-within-30-days"]}[tier]
            priority = "urgent" if tier == "HIGH" else "routine"
            inventory = "Diagnosis tercatat: " + episode["diagnosis"] + ". Daftar obat dari ringkasan pulang: " + "; ".join(episode["medications"]) + "."
            ending = " " + " ".join(activities) + " Ini rencana demo sintetis yang menunggu persetujuan manusia, bukan panduan klinis."
            narratives = ["Draf tindak lanjut. " + inventory + ending, "Ringkasan rencana pemantauan. " + inventory + ending]
            draft = {"plan_text": narratives[0], "satuseshat": {"careplan": {"title": "Draf tindak lanjut sintetis", "intent": "plan", "activity": activities}, "servicerequest": {"patientInstruction": "Tindak lanjut rutin pada " + source["followup_date"] + "; kontak rutin " + source["hotline"] + ". Menunggu persetujuan manusia.", "priority": priority}, "task": [{"code": code, "status": "requested", "priority": priority} for code in codes]}}
            self._prepared = {"ok": True, "source_input": source, "tier": tier, "care_intensity": activities, "allowed_plan_text": narratives, "draft_shape": draft, "reviewer_note": source.get("reviewer_note", "")}
        except (ValueError, TypeError, KeyError) as exc:
            self._prepared = {"ok": False, "error": "missing_or_invalid_facts", "reason": str(exc), "missing_facts": missing, "status": "DRAFT pending human approval", "label": "demo-heuristic-v1", "disclaimer": "Synthetic demo only; not clinically validated. No diagnosis, medication changes, or emergency advice."}
        return self._prepared

    def _exclude(self, output):
        self.stop(output)
        self.graph.exclude_branch_conditionally(self._id, output_name=output)

    def validated_facts(self) -> Message:
        result = self._prepare()
        if not result["ok"]:
            self._exclude("facts")
            return Message(text="")
        self._exclude("error")
        return Message(text=json.dumps(result, ensure_ascii=False))

    def fact_error(self) -> Message:
        result = self._prepare()
        if result["ok"]:
            self._exclude("error")
            return Message(text="")
        self._exclude("facts")
        return Message(text=json.dumps(result, ensure_ascii=False))

import json
import re
from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message

class SynCareDraftGuard(Component):
    display_name = "SynCare Deterministic Draft Guard"
    description = "Closed-vocabulary output validation; no invented clinical strings, schedules or contacts."
    inputs = [MessageTextInput(name="facts", display_name="Validated Facts", required=True), MessageTextInput(name="input_value", display_name="Gemini Draft JSON", required=True)]
    outputs = [Output(name="output", display_name="Guarded Draft JSON", method="guard_draft")]

    def guard_draft(self) -> Message:
        def text(value):
            return value.text if isinstance(value, Message) else str(value)
        try:
            facts = json.loads(text(self.facts))
            if facts.get("ok") is not True:
                raise ValueError("Fact gate did not approve generation")
            raw = text(self.input_value).strip()
            fence = re.fullmatch(r"```(?:json)?\s*(.*?)\s*```", raw, re.S | re.I)
            draft = json.loads(fence.group(1) if fence else raw)
            if not isinstance(draft, dict) or set(draft) != {"plan_text", "satuseshat"}:
                raise ValueError("Invalid top-level draft keys")
            expected = facts["draft_shape"]
            if draft["satuseshat"] != expected["satuseshat"]:
                raise ValueError("Resource shape or factual string outside deterministic allowlist")
            if draft["plan_text"] not in facts["allowed_plan_text"]:
                raise ValueError("Narrative contains text outside factual clinical-string allowlist")
            source = facts["source_input"]
            instruction = draft["satuseshat"]["servicerequest"]["patientInstruction"]
            for field in ("followup_date", "hotline"):
                if source[field] not in instruction:
                    raise ValueError("Supplied scheduling fact not preserved verbatim")
            # Defense in depth: all full calendar dates/phone-like digit runs must occur in supplied facts.
            generated = json.dumps(draft, ensure_ascii=False)
            supplied = json.dumps(source, ensure_ascii=False)
            for match in re.findall(r"\b(?:\d{4}-\d{2}-\d{2}|\d{1,2}[/-]\d{1,2}[/-]\d{2,4})\b|(?<!\w)\+?\d[\d ()-]{6,}\d(?!\w)", generated):
                if match not in supplied:
                    raise ValueError("Invented date or phone-like digit pattern")
            draft.update({"patient_id": source["patient_id"], "tier": facts["tier"], "care_intensity": facts["care_intensity"], "status": "DRAFT pending human approval", "label": source["f1_scored_output"]["label"], "missing_facts": [], "disclaimer": "Synthetic demo only; not clinically validated. FHIR-shaped resources are not a SATUSEHAT submission. No diagnosis, medication changes, or emergency advice. Pending human clinical approval.", "source_input": source})
            return Message(text=json.dumps(draft, ensure_ascii=False))
        except (ValueError, TypeError, KeyError) as exc:
            return Message(text=json.dumps({"error": "invalid_generated_plan", "reason": str(exc), "status": "DRAFT pending human approval", "label": "demo-heuristic-v1", "disclaimer": "Synthetic demo only; invalid plan rejected, not clinically validated."}, ensure_ascii=False))
